            ['name' => 'বাজার দর', 'slug' => 'market', 'icon' => '💹'],
            ['name' => 'সরকারি কৃষি সেবা', 'slug' => 'govt-service', 'icon' => '🏛️'],
            ['name' => 'কৃষি ঋণ ও ভর্তুকি', 'slug' => 'agri-loan', 'icon' => '💰'],
        ];

        $sort = 0;
        $catId = [];
        foreach ($categories as $c) {
            $cat = KnowledgeCategory::updateOrCreate(
                ['slug' => $c['slug']],
                ['name' => $c['name'], 'icon' => $c['icon'], 'status' => 'active', 'sort_order' => $sort++]
            );
            $catId[$c['slug']] = $cat->id;
        }

        $all = array_merge($this->greetingArticles(), $this->articles(), $this->governmentArticles());

        foreach ($all as $a) {
            $src = self::SRC[$a['s'] ?? 'AIS'];
            KnowledgeArticle::updateOrCreate(
                ['question' => $a['q']],
                [
                    'category_id' => $catId[$a['cat']] ?? null,
                    'title' => $a['t'],
                    'keywords' => $a['k'],
                    'answer' => $a['a'],
                    'source_name' => $src[0],
                    'source_url' => $src[1],
                    'source_type' => $src[2],
                    'status' => 'active',
                ]
            );
        }
    }

